fn render_ir(set: &[(&'static str, f64)]) -> Vec<f32> {
    let mut plugin = stave_tolex_vst3::Tolex::new();
    let bus = DebugBus::new();
    plugin.debug_attach(bus.clone());
    let table = plugin.param_table();
    for (n, v) in set {
        table
            .by_name(n)
            .unwrap_or_else(|| panic!("param '{n}'"))
            .set_plain(*v);
    }
    plugin.activate(FS, BLOCK);
    let mut out = Vec::with_capacity(IR_LEN);
    let mut in_l = vec![0.0f32; BLOCK];
    let mut in_r = vec![0.0f32; BLOCK];
    let mut out_l = vec![0.0f32; BLOCK];
    let mut out_r = vec![0.0f32; BLOCK];
    for b in 0..(IR_LEN / BLOCK) {
        in_l.fill(0.0);
        if b == 0 {
            in_l[0] = 0.01;
        }
        in_r.copy_from_slice(&in_l);
        let mut in_ptrs = [core::ptr::null_mut(); 2];
        let mut out_ptrs = [core::ptr::null_mut(); 2];
        let inb = AudioBuffer::from_slices(&mut in_ptrs, [&mut in_l, &mut in_r], BLOCK);
        let outb = AudioBuffer::from_slices(&mut out_ptrs, [&mut out_l, &mut out_r], BLOCK);
        let mut ctx = ProcessCtx {
            sample_rate: FS,
            frames: BLOCK,
            transport: None,
            input: inb,
            output: outb,
            aux: &[],
            params: stave_core::ParamBlock::empty(),
            events: &[],
        };
        plugin.process(&mut ctx);
        out.extend_from_slice(&out_l);
    }
    let _ = Arc::strong_count(&bus);
    out
}

/// 1/6-oct trend at the signature grid, re the 1 kHz band.
fn trend_at_sig_grid(ir: &[f32]) -> [f64; SIG_N] {
    let mut planner = FftPlanner::<f32>::new();
    let fft = planner.plan_fft_forward(FFT_N);
    let mut buf: Vec<Complex<f32>> = ir.iter().map(|x| Complex::new(*x, 0.0)).collect();
    buf.resize(FFT_N, Complex::new(0.0, 0.0));
    fft.process(&mut buf);
    let power: Vec<f64> = buf[..FFT_N / 2]
        .iter()
        .map(|c| f64::from(c.norm_sqr()))
        .collect();
    let bin_hz = f64::from(FS) / FFT_N as f64;
    let half = 2.0f64.powf(1.0 / 12.0);
    let mut out = [0.0f64; SIG_N];
    let mut ref_acc = (0.0f64, 0u32);
    for (i, slot) in out.iter_mut().enumerate() {
        let f = f64::from(SIG_F0) * f64::from(SIG_F1 / SIG_F0).powf(i as f64 / (SIG_N - 1) as f64);
        let b0 = ((f / half) / bin_hz).floor().max(1.0) as usize;
        let b1 = (((f * half) / bin_hz).ceil() as usize)
            .min(power.len() - 1)
            .max(b0 + 1);
        let mean = power[b0..=b1].iter().sum::<f64>() / (b1 - b0 + 1) as f64;
        *slot = 10.0 * mean.max(1e-30).log10();
        if (800.0..=1_250.0).contains(&f) {
            ref_acc.0 += *slot;
            ref_acc.1 += 1;
        }
    }
    let r = ref_acc.0 / ref_acc.1 as f64;
    for slot in out.iter_mut() {
        *slot -= r;
    }
    out
}

/// PROXIMITY — the pressure-gradient lean. Relative to the corpus
/// capture distance (3 cm, where the distilled signatures already
/// carry it): moving to 1 cm swells the lows, and the figure-8
/// ribbon (121) swells HARDER than the cardioid 57; pulling to
/// 40 cm sheds the close-mic bass. Measured at 90 Hz re the 1 kHz
/// band on rendered audio.
#[test]
fn the_mic_leans_in() {
    let base: &[(&'static str, f64)] = &[
        ("size", 2.0),
        ("resonance", 80.0),
        ("q", 0.85),
        ("damping", 0.75),
        ("back", 0.0),
        ("cab", 60.0),
        ("drive", 0.0),
        ("mass", 1.0),
        ("cone", 0.0),
        ("breakup", 0.6),
        ("doping", 0.35),
        ("position", 0.25),
        ("material", 0.0),
        ("speakers", 0.0),
        ("model", 0.0),
    ];
    let lf = |model: f64, mic_cm: f64| {
        let mut set = base.to_vec();
        set.push(("model", model));
        set.push(("mic", mic_cm));
        let t = trend_at_sig_grid(&render_ir(&set));
        // 90 Hz sits at grid index round(log(90/60)/log(266.7)/47…)
        let i = ((90.0f64 / f64::from(SIG_F0)).ln() / f64::from(SIG_F1 / SIG_F0).ln()
            * (SIG_N - 1) as f64)
            .round() as usize;
        t[i]
    };
    let rise_57 = lf(0.0, 1.0) - lf(0.0, 3.0);
    let rise_121 = lf(5.0, 1.0) - lf(5.0, 3.0);
    assert!(
        rise_57 >= 1.0,
        "57 at 1 cm rose only {rise_57:.2} dB — no proximity"
    );
    assert!(
        rise_121 >= rise_57 + 1.5,
        "the ribbon must lean harder: 121 {rise_121:.2} vs 57 {rise_57:.2} dB"
    );
    let shed_57 = lf(0.0, 40.0) - lf(0.0, 3.0);
    assert!(
        shed_57 <= -1.5,
        "pulling to 40 cm shed only {shed_57:.2} dB — close bass must go"
    );
}

#[test]
fn the_mics_wear_their_curves() {
    let base: &[(&'static str, f64)] = &[
        ("size", 2.0),
        ("resonance", 80.0),
        ("q", 0.85),
        ("damping", 0.75),
        ("back", 0.0),
        ("cab", 60.0),
        ("drive", 0.0),
        ("mic", 3.0),
        ("mass", 1.0),
        ("cone", 0.0),
        ("breakup", 0.6),
        ("doping", 0.35),
        ("position", 0.25),
        ("material", 0.0),
        ("speakers", 0.0),
        ("model", 0.0),
    ];
    let flat = trend_at_sig_grid(&render_ir(base));

    // params::MICS order: 57, 421, 58, 906, SM7, 121, 160, U47.
    let model_index: [(&str, f64); 7] = [
        ("421", 1.0),
        ("58", 2.0),
        ("906", 3.0),
        ("SM7", 4.0),
        ("121", 5.0),
        ("160", 6.0),
        ("U47", 7.0),
    ];

    for (name, sig) in SIGS {
        let idx = model_index
            .iter()
            .find(|(n, _)| *n == name)
            .unwrap_or_else(|| panic!("model '{name}' not shipped"))
            .1;
        let mut set = base.to_vec();
        set.push(("model", idx));
        let heard = trend_at_sig_grid(&render_ir(&set));

        let mut diffs = Vec::new();
        for i in 0..SIG_N {
            let f =
                f64::from(SIG_F0) * f64::from(SIG_F1 / SIG_F0).powf(i as f64 / (SIG_N - 1) as f64);
            if (100.0..=13_000.0).contains(&f) {
                diffs.push((heard[i] - flat[i]) - f64::from(sig[i]));
            }
        }
        let rms = (diffs.iter().map(|d| d * d).sum::<f64>() / diffs.len() as f64).sqrt();
        let max = diffs.iter().fold(0.0f64, |a, d| a.max(d.abs()));
        assert!(
            rms <= 0.9 && max <= 2.5,
            "{name}: engine wears the curve badly — rms {rms:.2} dB, max {max:.2} dB vs corpus"
        );
    }
}
